package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Formats an owner's customer code as {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3}
 * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first
 * three letters of the last name and {@code NNNN} a 4-digit zero-padded sequence number
 * (e.g. {@code LON-SMI-0007}).
 */
final class CustomerCode {

    private CustomerCode() {
    }

    static String format(String city, String lastName, int sequence) {
        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), sequence);
    }

    private static String prefix(String value) {
        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns a new owner's customer code before it is saved. The sequence is per-city: one
 * more than the number of owners already in this owner's city (see {@link Cities#matches}).
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int sequence = countInCity(owner, ownerRepository) + 1;
        owner.setCustomerCode(CustomerCode.format(owner.getCity(), owner.getLastName(), sequence));
    }

    private static int countInCity(Owner owner, OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (Cities.matches(existing, owner.getCity())) {
                count++;
            }
        }
        return count;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.MembershipLevel;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Emits an audit record for a successfully created owner. Runs after {@link SaveOwner}
 * so the generated id is available, publishing the owner id, customer code, registration
 * date and membership level to the dedicated {@code AUDIT} logger.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner) {
        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                MembershipLevel.of(owner));
    }
}

